def prose(v,key=''):
 if isinstance(v,str):
  if key in NO or v.startswith('https://'):return v
  return re.sub(r'(?<=[A-Za-z])(?=[0-9])|(?<=[0-9])(?=[A-Za-z])',' ',v)
 if isinstance(v,list):return [prose(t,key) for t in v]
 if isinstance(v,dict):return {k:prose(t,k) for k,t in v.items()}
 return v
